def allocate_pages(arr, m):
    if m > len(arr): return -1
    def is_possible(max_pages):
        students, pages = 1, 0
        for p in arr:
            if pages + p > max_pages:
                students += 1
                pages = p
            else:
                pages += p
        return students <= m
    low, high, ans = max(arr), sum(arr), -1
    while low <= high:
        mid = low + (high - low) // 2
        if is_possible(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

