def aggressive_cows(stalls, c):
    stalls.sort()
    def can_place(min_dist):
        count, last = 1, stalls[0]
        for i in range(1, len(stalls)):
            if stalls[i] - last >= min_dist:
                count += 1
                last = stalls[i]
        return count >= c
    low, high, ans = 1, stalls[-1] - stalls[0], 0
    while low <= high:
        mid = low + (high - low) // 2
        if can_place(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1
    return ans

